CREATE TABLE "DIM_MEMBER" (
  "MEME_KEY" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "MEME_ID" varchar(30) NOT NULL,
  "MESB_ID" varchar(30) NOT NULL,
  "FIRST_NAME" varchar(100) NOT NULL,
  "LAST_NAME" varchar(100) NOT NULL,
  "DATE_OF_BIRTH" date NOT NULL,
  "GENDER_CODE" varchar(1),
  "RELATIONSHIP_CODE" varchar(2),
  "EFFECTIVE_DATE" date NOT NULL,
  "END_DATE" date,
  "CURRENT_FLAG" boolean NOT NULL
);

CREATE TABLE "DIM_PLAN" (
  "PLPL_KEY" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "PLPL_ID" varchar(30) NOT NULL,
  "PLAN_CODE" varchar(20) NOT NULL,
  "PLAN_NAME" varchar(200) NOT NULL,
  "LINE_OF_BUSINESS_CODE" varchar(30) NOT NULL,
  "EFFECTIVE_DATE" date NOT NULL,
  "END_DATE" date,
  "CURRENT_FLAG" boolean NOT NULL
);

CREATE TABLE "DIM_GROUP" (
  "GRGR_KEY" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "GRGR_ID" varchar(30) NOT NULL,
  "GROUP_NUMBER" varchar(20) NOT NULL,
  "GROUP_NAME" varchar(200) NOT NULL,
  "STATE_CODE" varchar(2),
  "EFFECTIVE_DATE" date NOT NULL,
  "END_DATE" date,
  "CURRENT_FLAG" boolean NOT NULL
);

CREATE TABLE "DIM_DATE" (
  "DATE_KEY" int PRIMARY KEY NOT NULL,
  "FULL_DATE" date NOT NULL,
  "YEAR_NUMBER" int NOT NULL,
  "QUARTER_NUMBER" int NOT NULL,
  "MONTH_NUMBER" int NOT NULL,
  "DAY_NUMBER" int NOT NULL,
  "DAY_OF_WEEK_NAME" varchar(20) NOT NULL
);

CREATE TABLE "DIM_TRANSACTION_SOURCE" (
  "TXN_SRC_KEY" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "TXN_ID" bigint NOT NULL,
  "FILE_NAME" varchar(255) NOT NULL,
  "SENDER_ID" varchar(20) NOT NULL,
  "RECEIVED_TIMESTAMP" timestamptz NOT NULL
);

CREATE TABLE "FACT_ENROLLMENT" (
  "ENROLLMENT_FACT_KEY" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "MEME_KEY" bigint NOT NULL,
  "PLPL_KEY" bigint NOT NULL,
  "GRGR_KEY" bigint NOT NULL,
  "TXN_SRC_KEY" bigint NOT NULL,
  "COVERAGE_START_DATE_KEY" int NOT NULL,
  "COVERAGE_END_DATE_KEY" int,
  "MAINTENANCE_TYPE_CODE" varchar(3) NOT NULL,
  "ENROLLMENT_STATUS" varchar(15) NOT NULL,
  "ENROLLMENT_COUNT" int NOT NULL DEFAULT 1,
  "LOAD_TIMESTAMP" timestamptz NOT NULL
);

CREATE INDEX ON "DIM_MEMBER" ("MEME_ID");

CREATE INDEX ON "DIM_MEMBER" ("MESB_ID");

CREATE INDEX ON "DIM_MEMBER" ("CURRENT_FLAG");

CREATE INDEX ON "DIM_MEMBER" ("MEME_ID", "EFFECTIVE_DATE");

CREATE INDEX ON "DIM_PLAN" ("PLPL_ID");

CREATE INDEX ON "DIM_PLAN" ("PLAN_CODE");

CREATE INDEX ON "DIM_PLAN" ("LINE_OF_BUSINESS_CODE");

CREATE INDEX ON "DIM_PLAN" ("CURRENT_FLAG");

CREATE INDEX ON "DIM_PLAN" ("PLPL_ID", "EFFECTIVE_DATE");

CREATE INDEX ON "DIM_GROUP" ("GRGR_ID");

CREATE INDEX ON "DIM_GROUP" ("GROUP_NUMBER");

CREATE INDEX ON "DIM_GROUP" ("STATE_CODE");

CREATE INDEX ON "DIM_GROUP" ("CURRENT_FLAG");

CREATE INDEX ON "DIM_GROUP" ("GRGR_ID", "EFFECTIVE_DATE");

CREATE UNIQUE INDEX ON "DIM_DATE" ("FULL_DATE");

CREATE INDEX ON "DIM_DATE" ("YEAR_NUMBER");

CREATE INDEX ON "DIM_DATE" ("MONTH_NUMBER");

CREATE INDEX ON "DIM_TRANSACTION_SOURCE" ("TXN_ID");

CREATE INDEX ON "DIM_TRANSACTION_SOURCE" ("FILE_NAME");

CREATE INDEX ON "DIM_TRANSACTION_SOURCE" ("RECEIVED_TIMESTAMP");

CREATE INDEX ON "FACT_ENROLLMENT" ("MEME_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("PLPL_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("GRGR_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("TXN_SRC_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("COVERAGE_START_DATE_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("COVERAGE_END_DATE_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("MEME_KEY", "COVERAGE_START_DATE_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("PLPL_KEY", "COVERAGE_START_DATE_KEY");

CREATE INDEX ON "FACT_ENROLLMENT" ("GRGR_KEY", "COVERAGE_START_DATE_KEY");

COMMENT ON TABLE "DIM_MEMBER" IS 'Member Dimension

SCD Type 2.

Maintains historical versions
of member attributes.

MEME_KEY:
Warehouse-generated surrogate key.

MEME_ID:
Source/business member identifier.
';

COMMENT ON TABLE "DIM_PLAN" IS 'Benefit Plan Dimension

SCD Type 2.

Maintains historical versions
of benefit plan attributes.

PLPL_KEY:
Warehouse-generated surrogate key.

PLPL_ID:
Source/business plan identifier.
';

COMMENT ON TABLE "DIM_GROUP" IS 'Employer Group Dimension

Represents an organization or employer group
associated with healthcare enrollment.

SCD Type 2.

GRGR_KEY:
Warehouse-generated surrogate key.

GRGR_ID:
Source/business group identifier.
';

COMMENT ON TABLE "DIM_DATE" IS 'Calendar Dimension

DATE_KEY uses YYYYMMDD format.

Example:
20260827 = 27-Aug-2026
';

COMMENT ON TABLE "DIM_TRANSACTION_SOURCE" IS 'Transaction Source Dimension

Provides analytical lineage back to the
inbound 834 transaction.

TXN_SRC_KEY:
Warehouse-generated surrogate key.

TXN_ID:
Internal operational transaction identifier.
';

COMMENT ON TABLE "FACT_ENROLLMENT" IS 'Enrollment Fact

Grain:
One row per enrollment event.

Measures:
- ENROLLMENT_COUNT

Dimensions:
- Member
- Plan
- Group
- Transaction Source
- Coverage Start Date
- Coverage End Date

The dimension foreign keys use surrogate keys
to preserve historical dimensional context.
';

ALTER TABLE "FACT_ENROLLMENT" ADD FOREIGN KEY ("MEME_KEY") REFERENCES "DIM_MEMBER" ("MEME_KEY") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "FACT_ENROLLMENT" ADD FOREIGN KEY ("PLPL_KEY") REFERENCES "DIM_PLAN" ("PLPL_KEY") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "FACT_ENROLLMENT" ADD FOREIGN KEY ("GRGR_KEY") REFERENCES "DIM_GROUP" ("GRGR_KEY") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "FACT_ENROLLMENT" ADD FOREIGN KEY ("COVERAGE_START_DATE_KEY") REFERENCES "DIM_DATE" ("DATE_KEY") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "FACT_ENROLLMENT" ADD FOREIGN KEY ("COVERAGE_END_DATE_KEY") REFERENCES "DIM_DATE" ("DATE_KEY") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "FACT_ENROLLMENT" ADD FOREIGN KEY ("TXN_SRC_KEY") REFERENCES "DIM_TRANSACTION_SOURCE" ("TXN_SRC_KEY") DEFERRABLE INITIALLY IMMEDIATE;
